create extension if not exists pgcrypto;
create type tournament_status as enum ('draft','registration','verification','rating_review','player_pool_locked','auction_ready','auction_live','auction_paused','rosters_locked','competition','completed','cancelled');
create type tournament_role as enum ('player','captain','organizer','moderator','referee');
create type member_status as enum ('invited','active','suspended','removed');
create type rating_status as enum ('pending','verified','review_required','appealed','locked');
create type registration_status as enum ('draft','submitted','approved','rejected','withdrawn');
create type nomination_status as enum ('upcoming','active','completed','skipped');
create type auction_status as enum ('pending','open','paused','sold','unsold','cancelled','reversed');
create type acquisition_type as enum ('captain','auction','replacement','admin_assignment');
create type scouting_category as enum ('priority','backup','avoid','watch');
create type rating_assessment as enum ('much_weaker','slightly_weaker','accurate','slightly_stronger','much_stronger','unknown');
create type appeal_status as enum ('submitted','under_review','approved','rejected','withdrawn');
create type substitution_status as enum ('requested','under_review','approved','rejected','cancelled');

create table profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,username text unique,avatar_url text,discord_username text,steam_id text,country_code text check(country_code is null or country_code ~ '^[A-Z]{2}$'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table tournaments(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,season text,status tournament_status not null default 'draft',registration_opens_at timestamptz,registration_closes_at timestamptz,ratings_lock_at timestamptz,auction_starts_at timestamptz,starts_at timestamptz,ends_at timestamptz,created_by uuid not null references profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or starts_at is null or ends_at>starts_at));
create table tournament_members(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,status member_status not null default 'active',created_at timestamptz not null default now(),unique(tournament_id,user_id));
create table tournament_member_roles(member_id uuid not null references tournament_members(id) on delete cascade,role tournament_role not null,created_at timestamptz not null default now(),primary key(member_id,role));
create table tournament_players(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,user_id uuid not null references profiles(id),ign text not null,primary_role text,secondary_role text,region text,declared_mmr integer check(declared_mmr>=0),verified_mmr integer check(verified_mmr>=0),recent_peak_mmr integer check(recent_peak_mmr>=0),tournament_mmr integer check(tournament_mmr>=0),rating_confidence smallint check(rating_confidence between 0 and 100),rating_status rating_status not null default 'pending',availability_status text not null default 'available' check(availability_status in ('available','limited','unavailable')),is_reserve boolean not null default false,is_active boolean not null default true,is_eligible boolean not null default false,is_drafted boolean not null default false,registration_status registration_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tournament_id,user_id),unique(tournament_id,id));
create table teams(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,name text not null,short_tag text not null,logo_url text,accent_color text,captain_user_id uuid not null references profiles(id),starting_credits integer not null check(starting_credits>=0),credits_remaining integer not null check(credits_remaining>=0),captain_mmr integer not null default 0 check(captain_mmr>=0),current_team_mmr integer not null default 0 check(current_team_mmr>=0),roster_size integer not null default 0 check(roster_size>=0),max_roster_size integer not null check(max_roster_size>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tournament_id,name),unique(tournament_id,short_tag),unique(tournament_id,id));
create table tournament_rules(tournament_id uuid primary key references tournaments(id) on delete cascade,team_size integer not null check(team_size>0),starting_credits integer not null check(starting_credits>=0),minimum_bid integer not null check(minimum_bid>0),bid_increment integer not null check(bid_increment>0),initial_bid_seconds integer not null check(initial_bid_seconds>0),anti_snipe_threshold_seconds integer not null default 0 check(anti_snipe_threshold_seconds>=0),anti_snipe_extension_seconds integer not null default 0 check(anti_snipe_extension_seconds>=0),mmr_target integer,mmr_min integer,mmr_max integer,roles_enforced boolean not null default false,allow_custom_bid_jumps boolean not null default false,nomination_seconds integer not null check(nomination_seconds>0),allow_unsold_round boolean not null default false,unsold_minimum_bid integer check(unsold_minimum_bid>=0),allow_trades boolean not null default false,replacement_mmr_tolerance integer not null default 0 check(replacement_mmr_tolerance>=0),rules_version integer not null default 1 check(rules_version>0),locked_at timestamptz,updated_at timestamptz not null default now(),check(mmr_min is null or mmr_max is null or mmr_min<=mmr_max));
create table nomination_order(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,round_number integer not null check(round_number>0),position integer not null check(position>0),team_id uuid not null,status nomination_status not null default 'upcoming',completed_at timestamptz,foreign key(tournament_id,team_id) references teams(tournament_id,id),unique(tournament_id,round_number,position));
create unique index one_active_nomination_per_tournament on nomination_order(tournament_id) where status='active';
create table auctions(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,player_id uuid not null,nominating_team_id uuid not null,sequence_number integer not null check(sequence_number>0),status auction_status not null default 'pending',opening_bid integer not null check(opening_bid>=0),current_bid integer check(current_bid>=0),leading_team_id uuid,started_at timestamptz,closes_at timestamptz,closed_at timestamptz,revision bigint not null default 0 check(revision>=0),winning_team_id uuid,winning_bid integer check(winning_bid>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tournament_id,player_id) references tournament_players(tournament_id,id),foreign key(tournament_id,nominating_team_id) references teams(tournament_id,id),foreign key(tournament_id,leading_team_id) references teams(tournament_id,id),foreign key(tournament_id,winning_team_id) references teams(tournament_id,id),unique(tournament_id,sequence_number));
create table bids(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,auction_id uuid not null references auctions(id) on delete cascade,team_id uuid not null references teams(id),captain_user_id uuid not null references profiles(id),amount integer not null check(amount>0),request_id uuid not null unique,auction_revision_before bigint not null,auction_revision_after bigint,received_at timestamptz not null default now(),accepted boolean not null default false,rejection_reason text);
create table team_roster(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,team_id uuid not null,player_id uuid not null,acquisition_type acquisition_type not null,auction_id uuid references auctions(id),purchase_price integer check(purchase_price>=0),tournament_mmr_at_draft integer not null check(tournament_mmr_at_draft>=0),is_captain boolean not null default false,is_active boolean not null default true,is_substitute boolean not null default false,created_at timestamptz not null default now(),foreign key(tournament_id,team_id) references teams(tournament_id,id),foreign key(tournament_id,player_id) references tournament_players(tournament_id,id));
create unique index one_active_roster_per_player on team_roster(tournament_id,player_id) where is_active;
create table scouting_entries(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,captain_user_id uuid not null references profiles(id),player_id uuid not null references tournament_players(id) on delete cascade,category scouting_category not null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tournament_id,captain_user_id,player_id));
create table rating_reviews(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,player_id uuid not null references tournament_players(id),reviewer_user_id uuid not null references profiles(id),assessment rating_assessment not null,created_at timestamptz not null default now(),unique(tournament_id,player_id,reviewer_user_id));
create table appeals(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,player_id uuid not null references tournament_players(id),appeal_type text not null,reason text not null,evidence_url text,status appeal_status not null default 'submitted',reviewed_by uuid references profiles(id),resolution text,created_at timestamptz not null default now(),resolved_at timestamptz);
create table substitutions(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references tournaments(id) on delete cascade,team_id uuid not null references teams(id),outgoing_player_id uuid references tournament_players(id),incoming_player_id uuid not null references tournament_players(id),reason text not null,old_team_mmr integer not null,new_team_mmr integer not null,requested_by uuid not null references profiles(id),approved_by uuid references profiles(id),status substitution_status not null default 'requested',created_at timestamptz not null default now(),resolved_at timestamptz,check(outgoing_player_id is null or outgoing_player_id<>incoming_player_id));
create table audit_events(id uuid primary key default gen_random_uuid(),tournament_id uuid references tournaments(id) on delete set null,actor_user_id uuid references profiles(id),actor_role tournament_role,event_type text not null,entity_type text not null,entity_id uuid,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());

create index tournament_members_user_idx on tournament_members(user_id,tournament_id); create index tournament_players_pool_idx on tournament_players(tournament_id,is_eligible,is_active); create index teams_tournament_idx on teams(tournament_id); create index auctions_state_idx on auctions(tournament_id,status,sequence_number); create index bids_auction_idx on bids(auction_id,received_at); create index appeals_player_idx on appeals(player_id,status); create index audit_tournament_idx on audit_events(tournament_id,created_at desc);
create function is_tournament_role(tid uuid,wanted tournament_role) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from tournament_members m join tournament_member_roles r on r.member_id=m.id where m.tournament_id=tid and m.user_id=auth.uid() and m.status='active' and r.role=wanted)$$;
create function touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create function protect_player_admin_fields() returns trigger language plpgsql as $$begin if not is_tournament_role(old.tournament_id,'organizer') and (new.verified_mmr is distinct from old.verified_mmr or new.recent_peak_mmr is distinct from old.recent_peak_mmr or new.tournament_mmr is distinct from old.tournament_mmr or new.rating_confidence is distinct from old.rating_confidence or new.rating_status is distinct from old.rating_status or new.is_eligible is distinct from old.is_eligible or new.is_drafted is distinct from old.is_drafted) then raise exception 'administrative player fields are protected';end if;return new;end$$;
create trigger protect_player_fields before update on tournament_players for each row execute function protect_player_admin_fields();
create trigger profiles_touch before update on profiles for each row execute function touch_updated_at(); create trigger tournaments_touch before update on tournaments for each row execute function touch_updated_at(); create trigger players_touch before update on tournament_players for each row execute function touch_updated_at();
create function sync_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email,'Player'),new.raw_user_meta_data->>'avatar_url') on conflict(id) do update set display_name=coalesce(excluded.display_name,profiles.display_name),avatar_url=coalesce(excluded.avatar_url,profiles.avatar_url),updated_at=now();return new;end$$;
create trigger on_auth_user_sync after insert or update of raw_user_meta_data on auth.users for each row execute function sync_profile();

alter table profiles enable row level security; alter table tournaments enable row level security; alter table tournament_members enable row level security; alter table tournament_member_roles enable row level security; alter table tournament_players enable row level security; alter table teams enable row level security; alter table tournament_rules enable row level security; alter table nomination_order enable row level security; alter table auctions enable row level security; alter table bids enable row level security; alter table team_roster enable row level security; alter table scouting_entries enable row level security; alter table rating_reviews enable row level security; alter table appeals enable row level security; alter table substitutions enable row level security; alter table audit_events enable row level security;
create policy own_profile_read on profiles for select to authenticated using(id=auth.uid()); create policy own_profile_update on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy tournament_member_read on tournaments for select to authenticated using(exists(select 1 from tournament_members m where m.tournament_id=id and m.user_id=auth.uid() and m.status='active')); create policy organizer_manage_tournament on tournaments for all to authenticated using(is_tournament_role(id,'organizer')) with check(is_tournament_role(id,'organizer'));
create policy members_self_or_organizer on tournament_members for select to authenticated using(user_id=auth.uid() or is_tournament_role(tournament_id,'organizer')); create policy organizer_manage_members on tournament_members for all to authenticated using(is_tournament_role(tournament_id,'organizer')) with check(is_tournament_role(tournament_id,'organizer'));
create policy roles_visible_to_self_or_org on tournament_member_roles for select to authenticated using(exists(select 1 from tournament_members m where m.id=member_id and (m.user_id=auth.uid() or is_tournament_role(m.tournament_id,'organizer'))));
create policy player_pool_read on tournament_players for select to authenticated using(user_id=auth.uid() or is_eligible or is_tournament_role(tournament_id,'organizer')); create policy own_registration_insert on tournament_players for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from tournaments t where t.id=tournament_id and t.status='registration')); create policy own_registration_update on tournament_players for update to authenticated using(user_id=auth.uid() and exists(select 1 from tournaments t where t.id=tournament_id and t.status='registration')) with check(user_id=auth.uid()); create policy organizer_manage_players on tournament_players for all to authenticated using(is_tournament_role(tournament_id,'organizer')) with check(is_tournament_role(tournament_id,'organizer'));
create policy teams_member_read on teams for select to authenticated using(exists(select 1 from tournament_members m where m.tournament_id=teams.tournament_id and m.user_id=auth.uid() and m.status='active')); create policy organizer_manage_teams on teams for all to authenticated using(is_tournament_role(tournament_id,'organizer')) with check(is_tournament_role(tournament_id,'organizer'));
create policy rules_member_read on tournament_rules for select to authenticated using(exists(select 1 from tournament_members m where m.tournament_id=tournament_rules.tournament_id and m.user_id=auth.uid())); create policy organizer_manage_rules on tournament_rules for all to authenticated using(is_tournament_role(tournament_id,'organizer')) with check(is_tournament_role(tournament_id,'organizer'));
create policy nomination_member_read on nomination_order for select to authenticated using(exists(select 1 from tournament_members m where m.tournament_id=nomination_order.tournament_id and m.user_id=auth.uid())); create policy auction_member_read on auctions for select to authenticated using(exists(select 1 from tournament_members m where m.tournament_id=auctions.tournament_id and m.user_id=auth.uid())); create policy bids_organizer_read on bids for select to authenticated using(is_tournament_role(tournament_id,'organizer'));
create policy roster_member_read on team_roster for select to authenticated using(exists(select 1 from tournament_members m where m.tournament_id=team_roster.tournament_id and m.user_id=auth.uid()));
create policy scouting_owner_all on scouting_entries for all to authenticated using(captain_user_id=auth.uid() and is_tournament_role(tournament_id,'captain')) with check(captain_user_id=auth.uid() and is_tournament_role(tournament_id,'captain'));
create policy review_own_read on rating_reviews for select to authenticated using(reviewer_user_id=auth.uid() or is_tournament_role(tournament_id,'organizer')); create policy review_own_insert on rating_reviews for insert to authenticated with check(reviewer_user_id=auth.uid() and is_tournament_role(tournament_id,'captain'));
create policy appeals_owner_read on appeals for select to authenticated using(exists(select 1 from tournament_players p where p.id=appeals.player_id and p.user_id=auth.uid()) or is_tournament_role(tournament_id,'organizer')); create policy appeals_owner_insert on appeals for insert to authenticated with check(exists(select 1 from tournament_players p where p.id=player_id and p.user_id=auth.uid())); create policy appeals_organizer_update on appeals for update to authenticated using(is_tournament_role(tournament_id,'organizer')) with check(is_tournament_role(tournament_id,'organizer'));
create policy substitutions_parties_read on substitutions for select to authenticated using(requested_by=auth.uid() or is_tournament_role(tournament_id,'organizer')); create policy audit_organizer_read on audit_events for select to authenticated using(is_tournament_role(tournament_id,'organizer'));

create view public_tournament_summary with (security_barrier=true) as select id,name,slug,season,status,registration_opens_at,registration_closes_at,auction_starts_at,starts_at,ends_at from tournaments where status not in ('draft','cancelled');
create view public_player_pool with (security_barrier=true) as select p.id,p.tournament_id,p.ign,p.primary_role,p.secondary_role,p.region,p.tournament_mmr,p.is_reserve,p.is_drafted from tournament_players p join tournaments t on t.id=p.tournament_id where p.is_active and p.is_eligible and t.status not in ('draft','registration','verification','rating_review','cancelled');
create view public_teams with (security_barrier=true) as select tm.id,tm.tournament_id,tm.name,tm.short_tag,tm.logo_url,tm.accent_color,tm.current_team_mmr,tm.roster_size,tm.max_roster_size from teams tm join tournaments t on t.id=tm.tournament_id where t.status not in ('draft','cancelled');
create view public_auction_state with (security_barrier=true) as select a.id,a.tournament_id,a.player_id,a.nominating_team_id,a.sequence_number,a.status,a.opening_bid,a.current_bid,a.leading_team_id,a.started_at,a.closes_at,a.closed_at,a.revision,a.winning_team_id,a.winning_bid from auctions a join tournaments t on t.id=a.tournament_id where t.status in ('auction_live','auction_paused','rosters_locked','competition','completed');
grant select on public_tournament_summary,public_player_pool,public_teams,public_auction_state to anon,authenticated;
